(()=>{const id='ERP-WMS-DAILY';if(!tasks.some(t=>t.id===id)){tasks.push({id,title:'每日ERP和WMS库存数据对比',desc:'核对ERP与WMS库存，识别数量差异并确认处理方案。',owner:'agent',priority:'高',state:'review'});save();render()}const originalDetails=details;details=function(taskId){if(taskId===id)openCompare();else originalDetails(taskId)};let focusBefore;
function closeCompare(){document.getElementById('inventory-compare-overlay')?.remove();focusBefore?.focus()}
function openCompare(){if(parent!==window){parent.postMessage({type:'erp-open-inventory-conversation'},location.origin);return}focusBefore=document.activeElement;const task=tasks.find(t=>t.id===id);const overlay=document.createElement('div');overlay.id='inventory-compare-overlay';overlay.innerHTML=`<section class="compare-drawer" role="dialog" aria-modal="true" aria-labelledby="compare-title"><header><div><small>库存作业智能体 · AI 对话</small><h2 id="compare-title">每日ERP和WMS库存数据对比</h2></div><button class="compare-close" aria-label="关闭库存对比">×</button></header><div class="compare-body"><div class="compare-bubble user">请核对今日ERP与WMS库存，分析差异并给出处理建议。</div><div class="compare-bubble"><strong>✦ 已完成库存对比</strong><p>按物料编码、库存组织、仓库和批次匹配了 128 条示例库存记录，其中 126 条一致，2 条存在数量差异。</p><div class="compare-alert">识别到异常 · 2 项库存数量不一致</div><table><thead><tr><th>物料 / 仓库</th><th>ERP</th><th>WMS</th><th>差异</th></tr></thead><tbody><tr><td>A100控制器 / 原料仓</td><td>320</td><td>308</td><td>-12</td></tr><tr><td>B200电源模块 / 成品仓</td><td>120</td><td>128</td><td>+8</td></tr></tbody></table><p>可能原因：出入库交易同步延迟、库存统计口径不一致，或实物作业尚未完成账务登记。建议核对相关单据后选择处理方案。</p><small>示例数据 · 当前为交互演示</small></div><div class="compare-bubble"><strong>选择解决方案</strong><div class="compare-solutions">${[['重新同步库存交易','核查接口失败记录，补传遗漏的出入库交易，再重新对比。'],['核对库存统计口径','统一仓库、批次、库存状态和截止时间，按同一口径重新核对。'],['发起实物盘点与差异调整','安排差异物料盘点，复核原因并按审批流程处理库存调整。']].map((x,i)=>`<button class="compare-solution" data-solution="${i}"><b>0${i+1}　${x[0]}${i===0?'<small class="inventory-it-notice">需要 IT 同事协助</small>':''}</b><span>${x[1]}</span></button>`).join('')}</div><div id="compare-result" role="status">${task.state==='done'?'✓ 已解决“ERP和WMS库存数据问题”':''}</div></div><div id="compare-chat"></div></div><form class="compare-input"><input aria-label="继续询问库存对比" placeholder="继续询问差异原因或处理细节…" required><button>发送 ↑</button></form></section>`;document.body.append(overlay);overlay.querySelector('.compare-close').onclick=closeCompare;overlay.onclick=e=>{if(e.target===overlay)closeCompare()};overlay.querySelectorAll('[data-solution]').forEach(b=>b.onclick=()=>{overlay.querySelectorAll('[data-solution]').forEach(x=>{x.classList.toggle('chosen',x===b);x.setAttribute('aria-pressed',String(x===b))});task.state='done';task.resolution=b.querySelector('b').textContent;save();render();document.getElementById('compare-result').textContent='✓ 已选择方案：'+b.querySelector('b').textContent+'。已解决“ERP和WMS库存数据问题”。';document.getElementById('compare-result').scrollIntoView({block:'nearest',behavior:'smooth'})});overlay.querySelector('form').onsubmit=e=>{e.preventDefault();const input=e.target.querySelector('input'),chat=overlay.querySelector('#compare-chat');const u=document.createElement('div');u.className='compare-bubble user';u.textContent=input.value;chat.append(u);const a=document.createElement('div');a.className='compare-bubble';a.textContent='建议先按物料、仓库和批次定位差异，再核对出入库单据、接口同步日志与截止时间。确认原因后，可选择上方对应方案处理并复核结果。';chat.append(a);input.value='';a.scrollIntoView({block:'nearest',behavior:'smooth'})};overlay.querySelector('.compare-close').focus()}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeCompare()});})();
